using namespace std;

//calculate score
int score(string s){
    int n = s.size();
    int score = 0;
    for(int i =0 ; i<=n-2 ; i++){
        if(s[i]==s[i+1]){
            score++;
        }
    }
    return score;
}

//generate rotations
vector<string> rotations(string s){
    vector<string>result;
    result.push_back(s);
    for(int i =0 ; i<= s.size()-2 ; i++){
        cout<<s<<endl;
        s.push_back(s[0]);
        s.erase(0,1);
        result.push_back(s);
        cout<<s<<endl;
    }
    return result;
}

int countRotations(string s, int k) {
    vector<string> result = rotations(s);
    int ans = 0;
    for(auto &s:result){
        int sc = score(s);
        if(sc==k){
            ans++;
        }
    }
    return ans;
}

int countGoodRotations(vector<int>& nums) {
    int ans = 0;
    int n = nums.size();
    int total_sum = 0;
    long long first_half_sum = 0;
    for(int i=0 ; i<n ; i++){
        if(i<n/2){
            first_half_sum+=nums[i];
        }
        total_sum+=nums[i];
    }
    long long second_half_sum = total_sum - first_half_sum;

    if(first_half_sum > second_half_sum){
        ans++;
    }

    int j = n/2;
    for(int i=0 ; i<=n-2 ; i++){
        first_half_sum += nums[j];
        first_half_sum -= nums[i];

        second_half_sum += nums[i];
        second_half_sum -= nums[j];

        if(first_half_sum>second_half_sum){
            ans++;
        }
        
        j=(j+1)%n;
    }

    return ans;
}


int countGroups(vector<int>& position, vector<int>& speed, int distance) {
    int ans = 1;
    int t = 0;
    for(int i = speed.size()-1 ; i>=1 ; i--){
        int difference = ((position[i]+(speed[i]*t)) - (position[i-1]+(speed[i-1]*t)) );
        if((speed[i] >= speed[i-1]) && difference>distance ){
            ans++;
        }
        else{
            speed[i-1] = speed[i];
            position[i-1] = position[i];
        }
        t++;
    }
    return ans;
}

